#!/usr/bin/env python3
"""Generates tests/common/wycheproof_x25519.inc and wycheproof_p256.inc from
the Project Wycheproof test vectors (Apache-2.0, https://github.com/C2SP/wycheproof).

    python3 tools/gen_wycheproof.py --x25519 x25519_test.json \
        --p256 ecdsa_secp256r1_sha256_test.json

The inputs are testvectors_v1/x25519_test.json and
testvectors_v1/ecdsa_secp256r1_sha256_test.json; their SHA-256 is written into
the generated files. ECDSA signatures are converted from DER to the raw
r||s form the accelerator takes, with a strict DER parser: vectors whose
encoding is invalid DER, or whose r/s do not fit 32 bytes, test the ASN.1
layer (not the code under test) and are dropped; their number is reported in
the file header.
"""
import argparse
import hashlib
import json
import os


def sha256_file(path):
    with open(path, "rb") as f:
        return hashlib.sha256(f.read()).hexdigest()


def der_len(b, i):
    """Returns (length, next index) for a strictly minimal DER length, or None."""
    if i >= len(b):
        return None
    first = b[i]
    if first < 0x80:
        return first, i + 1
    n = first & 0x7F
    if n == 0 or n > 2 or i + 1 + n > len(b):
        return None
    v = int.from_bytes(b[i + 1:i + 1 + n], "big")
    if v < 0x80 or (n == 2 and v < 0x100):  # long form only where the short form cannot hold it
        return None
    return v, i + 1 + n


def der_int(b, i):
    if i >= len(b) or b[i] != 0x02:
        return None
    r = der_len(b, i + 1)
    if r is None:
        return None
    ln, j = r
    if ln == 0 or j + ln > len(b):
        return None
    body = b[j:j + ln]
    if body[0] & 0x80:  # negative
        return None
    if ln > 1 and body[0] == 0 and not (body[1] & 0x80):  # non-minimal
        return None
    return int.from_bytes(body, "big"), j + ln


def der_sig_to_raw(sig):
    if len(sig) < 2 or sig[0] != 0x30:
        return None
    r = der_len(sig, 1)
    if r is None:
        return None
    ln, i = r
    if i + ln != len(sig):
        return None
    a = der_int(sig, i)
    if a is None:
        return None
    rv, i = a
    b = der_int(sig, i)
    if b is None:
        return None
    sv, i = b
    if i != len(sig) or rv >= 1 << 256 or sv >= 1 << 256:
        return None
    return rv.to_bytes(32, "big") + sv.to_bytes(32, "big")


def c_str(s):
    return '"' + s.replace("\\", "\\\\").replace('"', '\\"') + '"'


HEADER = """/* GENERATED by tools/gen_wycheproof.py - do not edit.
 * Source: Project Wycheproof (Apache-2.0), {name}, sha256 {digest}.
 * {note} */
"""


def gen_x25519(path, out):
    d = json.load(open(path))
    rows = []
    for g in d["testGroups"]:
        for t in g["tests"]:
            res = {"valid": 1, "acceptable": 2}.get(t["result"])
            if res is None:
                raise SystemExit("unexpected x25519 result " + t["result"])
            rows.append((t["tcId"], res, t["private"], t["public"], t["shared"]))
    with open(out, "w") as f:
        f.write(HEADER.format(name=os.path.basename(path), digest=sha256_file(path),
                              note="%d vectors; result 1 = valid, 2 = acceptable." % len(rows)))
        f.write("static const struct { int tc; int result; const char *priv, *pub, *shared; } k_wp_x25519[] = {\n")
        for tc, res, priv, pub, shared in rows:
            f.write("    {%d, %d, %s, %s, %s},\n" % (tc, res, c_str(priv), c_str(pub), c_str(shared)))
        f.write("};\n")
    print("x25519: %d vectors" % len(rows))


def gen_p256(path, out):
    d = json.load(open(path))
    rows, dropped = [], 0
    for g in d["testGroups"]:
        pub = g["publicKey"]["uncompressed"]
        for t in g["tests"]:
            res = {"valid": 1, "invalid": 0}.get(t["result"])
            if res is None:
                raise SystemExit("unexpected ecdsa result " + t["result"])
            raw = der_sig_to_raw(bytes.fromhex(t["sig"]))
            if raw is None:
                dropped += 1
                continue
            rows.append((t["tcId"], res, pub, t["msg"], raw.hex()))
    with open(out, "w") as f:
        f.write(HEADER.format(name=os.path.basename(path), digest=sha256_file(path),
                              note="%d vectors kept, %d dropped (invalid DER or r/s over 32 bytes); "
                                   "result 1 = valid, 0 = invalid." % (len(rows), dropped)))
        f.write("static const struct { int tc; int result; const char *pub, *msg, *sig; } k_wp_p256[] = {\n")
        for tc, res, pub, msg, sig in rows:
            f.write("    {%d, %d, %s, %s, %s},\n" % (tc, res, c_str(pub), c_str(msg), c_str(sig)))
        f.write("};\n")
    print("p256: %d vectors kept, %d dropped" % (len(rows), dropped))


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--x25519", required=True)
    ap.add_argument("--p256", required=True)
    ap.add_argument("--out-dir", default=os.path.join(os.path.dirname(__file__), "..", "tests", "common"))
    a = ap.parse_args()
    gen_x25519(a.x25519, os.path.join(a.out_dir, "wycheproof_x25519.inc"))
    gen_p256(a.p256, os.path.join(a.out_dir, "wycheproof_p256.inc"))


if __name__ == "__main__":
    main()
